package org.apache.commons.cli.options;

import org.apache.commons.cli.Option;
import org.apache.commons.cli.OptionGroup;
import org.apache.commons.cli.Options;
import org.junit.Test;
import org.junit.Before;
import org.junit.Rule;
import org.junit.rules.ExpectedException;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;

public class AddOptionsTests {
    private Options sourceOptions;
    private Options targetOptions;

    @Rule
    public ExpectedException thrown = ExpectedException.none();

    @Before
    public void setUp() {
        sourceOptions = new Options();
        targetOptions = new Options();
    }

    @Test
    public void testAddOptionsWithSingleOption() {
        sourceOptions.addOption("a", "option a");

        Options result = targetOptions.addOptions(sourceOptions);

        assertSame(targetOptions, result);
        assertTrue(targetOptions.hasOption("a"));
        assertFalse(targetOptions.hasOption("b"));
    }

    @Test
    public void testAddOptionsWithMultipleOptions() {
        sourceOptions.addOption("a", "option a");
        sourceOptions.addOption("b", "option b");
        sourceOptions.addOption("c", "option c");

        targetOptions.addOptions(sourceOptions);

        assertTrue(targetOptions.hasOption("a"));
        assertTrue(targetOptions.hasOption("b"));
        assertTrue(targetOptions.hasOption("c"));
    }

    @Test
    public void testAddOptionsWithDuplicateKeyShouldThrowException() {
        sourceOptions.addOption("a", "option a");
        targetOptions.addOption("a", "existing option a");

        thrown.expect(IllegalArgumentException.class);
        thrown.expectMessage("Duplicate key: a");

        targetOptions.addOptions(sourceOptions);
    }

    @Test
    public void testAddOptionsWithOptionGroup() {
        OptionGroup group = new OptionGroup();
        group.addOption(new Option("a", "option a"));
        group.addOption(new Option("b", "option b"));
        sourceOptions.addOptionGroup(group);

        targetOptions.addOptions(sourceOptions);

        assertTrue(targetOptions.getOptionGroups().contains(group));
        assertTrue(targetOptions.hasOption("a"));
        assertTrue(targetOptions.hasOption("b"));
    }

    @Test
    public void testAddOptionsWithMultipleOptionGroups() {
        OptionGroup group1 = new OptionGroup();
        group1.addOption(new Option("a", "option a"));
        group1.addOption(new Option("b", "option b"));

        OptionGroup group2 = new OptionGroup();
        group2.addOption(new Option("c", "option c"));
        group2.addOption(new Option("d", "option d"));

        sourceOptions.addOptionGroup(group1);
        sourceOptions.addOptionGroup(group2);

        targetOptions.addOptions(sourceOptions);

        assertEquals(2, targetOptions.getOptionGroups().size());
        assertTrue(targetOptions.hasOption("a"));
        assertTrue(targetOptions.hasOption("b"));
        assertTrue(targetOptions.hasOption("c"));
        assertTrue(targetOptions.hasOption("d"));
    }

    @Test
    public void testAddOptionsWithMixedOptionsAndGroups() {
        sourceOptions.addOption("x", "option x");
        sourceOptions.addOption("y", "option y");

        OptionGroup group = new OptionGroup();
        group.addOption(new Option("a", "option a"));
        group.addOption(new Option("b", "option b"));
        sourceOptions.addOptionGroup(group);

        targetOptions.addOptions(sourceOptions);

        assertTrue(targetOptions.hasOption("x"));
        assertTrue(targetOptions.hasOption("y"));
        assertTrue(targetOptions.hasOption("a"));
        assertTrue(targetOptions.hasOption("b"));
        assertEquals(1, targetOptions.getOptionGroups().size());
    }

    @Test
    public void testAddOptionsToNonEmptyTarget() {
        targetOptions.addOption("z", "existing option z");
        sourceOptions.addOption("a", "option a");
        sourceOptions.addOption("b", "option b");

        targetOptions.addOptions(sourceOptions);

        assertTrue(targetOptions.hasOption("z"));
        assertTrue(targetOptions.hasOption("a"));
        assertTrue(targetOptions.hasOption("b"));
    }

    @Test
    public void testAddOptionsWithLongAndShortOptions() {
        sourceOptions.addOption(Option.builder("a")
                .longOpt("alpha")
                .desc("alpha option")
                .build());

        sourceOptions.addOption(Option.builder()
                .longOpt("beta")
                .desc("beta option")
                .build());

        targetOptions.addOptions(sourceOptions);

        assertTrue(targetOptions.hasOption("a"));
        assertTrue(targetOptions.hasLongOption("alpha"));
        assertTrue(targetOptions.hasLongOption("beta"));
    }

    @Test
    public void testAddOptionsReturnsThis() {
        sourceOptions.addOption("a", "option a");

        Options result = targetOptions.addOptions(sourceOptions);

        assertSame(targetOptions, result);
    }

    @Test
    public void testAddOptionsWithEmptySource() {
        targetOptions.addOptions(sourceOptions);

        assertEquals(0, targetOptions.getOptions().size());
        assertEquals(0, targetOptions.getOptionGroups().size());
    }

    @Test
    public void testAddOptionsWithNullKeyOption() {
        Option optionWithNullKey = new Option(null, "option with null key");
        Options customSource = new Options();
        customSource.addOption(optionWithNullKey);

        targetOptions.addOptions(customSource);

        // Should not throw exception for null key
        assertEquals(1, targetOptions.getOptions().size());
    }

    @Test
    public void testAddOptionsPreservesOptionProperties() {
        Option originalOption = Option.builder("t")
                .longOpt("test")
                .desc("test description")
                .required(true)
                .hasArg(true)
                .type(Integer.class)
                .build();

        sourceOptions.addOption(originalOption);
        targetOptions.addOptions(sourceOptions);

        Option addedOption = targetOptions.getOption("t");
        assertNotNull(addedOption);
        assertEquals("test", addedOption.getLongOpt());
        assertEquals("test description", addedOption.getDescription());
        assertTrue(addedOption.isRequired());
        assertTrue(addedOption.hasArg());
        assertEquals(Integer.class, addedOption.getType());
    }
}
